(2, '2025-02-27', 'Free HTML5 Games', '9149071729239252707.6.Blog1.png', '<p>Why Jambo Games Are the Best Place to Play 100% Free HTML5 Games</p>\r\n', 's', 's', 's', 's', 1),
(3, '2025-03-06', 'Bubble Pop smart free game', '5034949149071729239252707.6.Blog1.png', '<p>Bubble Pop Smart is a fun and addictive free game designed to test your reflexes and strategy.&nbsp;</p>\r\n', 'Bubble Pop smart free game', 'Players can enjoy different game modes, from classic timed challenges to endless play, where the goal is to achieve the highest score possible. The game starts easy but gradually increases in difficulty, making it suitable for players of all ages. Special power-ups and boosters help clear bubbles faster, adding a strategic element to the game.  Bubble Pop Smart features simple one-touch controls, making it easy to play yet challenging to master. Compete with friends, track high scores, and unlock achievements to stay motivated. The game is lightweight, runs smoothly on all devices, and does not require an internet connection, making it perfect for playing anytime, anywhere.  If you love bubble-popping games, Bubble Pop Smart is the perfect choice for endless fun. Download now and start popping!', 'Bubble Pop smart free game', 'Bubble Pop smart free game', 1),
(4, '2025-03-06', 'Spider Solitaire free game', '7298209149071729239252707.6.Blog1.png', '<p>Spider Solitaire is a timeless and addictive free card game that challenges your strategy and patience. The game follows the traditional solitaire rules</p>\r\n', 'timeless', 'Spider Solitaire', 'Spider Solitaire smart free game', 'Vishal', 1),
(5, '2025-03-06', 'Knife Fruit', '7136379149071729239252707.6.Blog1.png', '<p>It sounds like you&#39;re looking for a &quot;Knife Fruit&quot; smart game concept, similar to <em>Fruit Ninja</em> but possibly with a unique twist. Here are some ideas for a <em>Knife Fruit</em> game:</p>\r\n', 'Knife Fruit', 'Knife Fruit', 'Knife Fruit', 'Knife Fruit', 1);

